def tag_existing_demo_products(apps, schema_editor):
    """Assign the known demo garments once, leaving unrelated products unisex."""
    Product = apps.get_model("marketplace", "Product")
    ProductVariant = apps.get_model("marketplace", "ProductVariant")
    database = schema_editor.connection.alias
    for prefix, collection in DEMO_COLLECTIONS.items():
        if collection == "UNISEX":
            continue
        products = ProductVariant.objects.using(database).filter(
            sku__startswith=prefix + "-"
        ).values_list("product_id", flat=True)
        Product.objects.using(database).filter(
            pk__in=products, collection="UNISEX"
        ).update(collection=collection)


